mapper.select:


SELECT DISTINCT
  COUNT(1) AS Total
FROM
  EXPLOIT.STOJOU STOJOU
  LEFT JOIN EXPLOIT.ITMMASTER ITMMASTER ON ITMMASTER.ITMREF_0 = STOJOU.ITMREF_0
WHERE
  STOJOU.STOFCY_0 = #{Site}
  AND (
    STOJOU.CREDAT_0 BETWEEN CONVERT(DATE, #{DateFrom}, 23) AND CONVERT(DATE, #{DateTo}, 23)
  ) 

    AND (
      STOJOU.ITMREF_0 LIKE #{PnOrName}
      OR ITMMASTER.ITMDES1_0 LIKE #{PnOrName}
      OR ITMMASTER.ITMDES2_0 LIKE #{PnOrName}
    )

  --  6: Receive 
  --  10: workorder
  --  17: Supplier Invoice
  AND STOJOU.VCRTYPREG_0 != 17
